/// <summary>
/// The <c>AVARegisterASNItemsIDisposable</c> represents a iDisposable interface for register ASNItem process
/// </summary>
/// <remarks>
/// 
/// </remarks>
class AVARegisterASNItemsIDisposable implements System.IDisposable
{
    public  AVARegisterOutboundSortContainer    aktiveProcess;
    private Map                                 licensePlateToRegister;
    public  WHSLicensePlateId                   lastLicensePlateToRegister;

    static AVARegisterASNItemsIDisposable instance;

}

Method.Source:
protected void new()
{
    if (!AVARegisterASNItemsIDisposable::current())
    {
        instance = this;
    }
    else
    {
        instance = AVARegisterASNItemsIDisposable::current();
    }
}

/// <summary>
/// AVA_
/// </summary>
/// <returns>
/// Current instance of <c>AVARegisterASNItemsIDisposable</c>
/// </returns>
/// <remarks>
/// AVA_
/// </remarks>
public static AVARegisterASNItemsIDisposable current()
{
    return instance;
}

/// <summary>
/// Methode to get the license plate issue for the container license plate
/// </summary>
/// <param name = "_licensePlateToRegister">
/// The Container/ Licenplate to register on
/// </param>
/// <param name = "_setlastLicensePlateToRegister">
/// Set true to set the last get Value
/// </param>
/// <returns>
/// The license Plate Issue for the to register license Plate
/// </returns>
public WHSLicensePlateId loopUpLicensePlateToRegister(WHSLicensePlateId _licensePlateToRegister, boolean _setlastLicensePlateToRegister = true)
{
    WHSLicensePlateId  licensePlateIssue;

    if (licensePlateToRegister
     && licensePlateToRegister.exists(_licensePlateToRegister))
    {
        licensePlateIssue = licensePlateToRegister.lookup(_licensePlateToRegister);

        if (_setlastLicensePlateToRegister)
        {
            lastLicensePlateToRegister = _licensePlateToRegister;
        }
    }

    return licensePlateIssue;
}

/// <summary>
/// Methode to fill the license plate mapping: to register licenplate  = issue license plate
/// </summary>
/// <param name = "_licensePlateToRegister">
/// the licenses plate to register on
/// </param>
/// <param name = "_licensePlateIssue">
/// the licenplate where the transaktion posted on
/// </param>
public void addLicensePlateToRegister(WHSLicensePlateId   _licensePlateToRegister,
                                      WHSLicensePlateId   _licensePlateIssue)
{
    if (!licensePlateToRegister)
    {
        licensePlateToRegister = new Map(Types::String, Types::String);
    }

    licensePlateToRegister.insert(_licensePlateToRegister, _licensePlateIssue);
}

public static AVARegisterASNItemsIDisposable construct()
{
    AVARegisterASNItemsIDisposable  registerASNItemsIDisposable;

    registerASNItemsIDisposable = new AVARegisterASNItemsIDisposable();

    return registerASNItemsIDisposable;
}
